INSERT INTO `author` VALUES (1,'Hayfa Mcbride','Hayfa McBride is a biomedical systems specialist and contributing writer passionate about human-centered medical technology. Having worked closely with clinical teams and hospital operations, he writes about how surgical robotics, rehabilitation devices, and smart automation can safely support overburdened healthcare staff without losing the human touch.','images/authors/author_6b0498875d36f.jpg'),(2,'Dr. Elena Rostova','Elena is a biomedical engineer and health-tech writer exploring the intersection of clinical surgery, machine vision, and autonomous medical devices.','images/authors/author_6b04a0985f7fa.jpg'),(3,'Marcus Vance','Marcus is an industrial automation consultant with 12 years of experience designing smart manufacturing workflows and robotic supply chains.','images/authors/author_6b04a23f0ed78.jpg'),(4,'Kenji Takahashi','Kenji specializes in actuator kinematics and biomimetic hardware, translating biological movement into next-generation mechanical systems.','images/authors/author_6b04a3e817500.jpg'),(5,'Sarah Jenkins','Sarah is a former high school STEM teacher turned EdTech analyst who writes about accessible classroom technology and inclusive digital learning.','images/authors/author_6b04a58530e90.jpg'),(6,'Dr. Aris Thorne','Aris holds a PhD in computational linguistics and leads research on conversational interfaces, intent recognition, and human-robot dialogue.','images/authors/author_6b04a785c51d6.jpg'),(7,'Amara Okafor','Amara is a geriatric care specialist and assistive-tech advocate focused on human-centered robotics that preserve dignity and independence.','images/authors/author_6b04a935e0058.jpg'),(8,'Devon Brooks','Devon is a full-stack robotics systems architect building simulation pipelines, edge-AI inference tools, and open-source control firmware.','images/authors/author_6b04aa9d2a1de.jpg'),(9,'Claire Beaumont','Claire is a technology policy correspondent covering digital governance, algorithmic accountability, and international robotics legislation.','images/authors/author_6b04ac4be0902.jpg'),(10,'Leo Morales','Leo is a digital culture journalist tracking viral algorithms, synthetic media trends, and the creator economy.','images/authors/author_6b04ae6e314d5.jpg'),(11,'Hannah Lindqvist','Hannah writes about sustainable agritech, environmental robotics, and climate-resilient farming innovations.','images/authors/author_6b04afaa377d0.jpg'),(12,'Dr. Julian Mercer','Julian is a technology ethicist and cognitive scientist studying human-machine trust, emotional attachment, and responsible AI design.','images/authors/author_6b04b15f5d924.jpg');
/*!40000 ALTER TABLE `author` ENABLE KEYS */;
